package com.retailflow.pos.product;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.retailflow.pos.product.dto.ProductDTO;import com.retailflow.pos.stock.StockMovementService;import java.math.BigDecimal;import org.junit.jupiter.api.Test;
class ProductServiceTest{@Test void createsProduct(){var repo=mock(ProductRepository.class);var stock=mock(StockMovementService.class);when(repo.save(any())).thenAnswer(i->i.getArgument(0));var service=new ProductService(repo,stock);var result=service.save(new ProductDTO(null,"Shirt","SKU-1","Apparel",new BigDecimal("5"),new BigDecimal("100"),null,null,BigDecimal.TEN,new BigDecimal("80"),Product.UnitType.PIECE,"123"));assertEquals("Shirt",result.getName());verify(repo).save(any(Product.class));}}
